INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('1', 'news', 'เปิดรับสมัครนิสิตใหม่ ระดับปริญญาตรี ประจำปีการศึกษา 2570', 'Undergraduate Admission Open for Academic Year 2027', '2027学年本科招生正式开始', 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม เปิดรับสมัครบุคคลเข้าศึกษาต่อระดับปริญญาตรี หลักสูตรดุริยางคศาสตรบัณฑิต และการศึกษาบัณฑิต สมัครได้ผ่านระบบ TCAS และรับตรง', 'College of Music, MSU invites applications for undergraduate degree programs in Music Performance, Music Education and Thai Music.', '玛哈沙拉坎大学音乐学院招收音乐表演、音乐教育及泰国音乐专业本科生。欢迎国际学生报考。', 'https://picsum.photos/id/1082/800/450', NULL, 'https://music.msu.ac.th/admission', NULL, 'วิทยาลัยดุริยางคศิลป์ มมส', '0', '1', '5', '2026-10-26 14:48:17');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('2', 'concerts', 'MSU Symphony Orchestra Annual Gala Concert 2026', 'MSU Symphony Orchestra Annual Gala Concert 2026', '2026玛哈沙拉坎大学交响乐团年度盛典音乐会', 'การแสดงดนตรีซิมโฟนีออร์เคสตราครั้งยิ่งใหญ่ บรรเลงบทเพลงคลาสสิกระดับโลกและบทเพลงไทยประยุกต์ โดยคณาจารย์และนิสิตวิทยาลัยดุริยางคศิลป์ ณ หอแสดงดนตรีวิทยาลัย', 'Grand Symphony Orchestra performance featuring classical masterpieces and contemporary Thai compositions.', '盛大交响乐团演出，呈献世界经典与当代泰国音乐作品，由音乐学院师生联合呈现。', 'https://picsum.photos/id/1080/800/450', NULL, 'https://music.msu.ac.th/events/concert2026', '2026-10-29', 'หอแสดงดนตรีวิทยาลัยดุริยางคศิลป์', '0', '1', '1', '2026-10-26 11:05:48');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('6', 'rooms', 'แผนผังอาคารและห้องปฏิบัติการทางดนตรี', 'Campus Building Directory & Wayfinding', '学院建筑与琴房分布指南', 'ชั้น 1: หอแสดงดนตรี, ห้องประชุม, คาเฟ่\\nชั้น 2: ห้องสำนักงาน, ห้องพักอาจารย์, ห้องบรรยาย\\nชั้น 3: สตูดิโอบันทึกเสียง, ห้อง Mac Lab\\nชั้น 4: ห้องซ้อมรวมวง Ensemble และห้องซ้อมเดี่ยว 50 ห้อง', 'Floor 1: Concert Hall & Cafe | Floor 2: Office & Classrooms | Floor 3: Sound Studios & Mac Lab | Floor 4: Practice Rooms.', '1层：音乐厅与大厅 | 2层：行政办公室与教室 | 3层：录音棚与电脑音乐室 | 4层：单人与合奏琴房。', 'https://picsum.photos/id/1048/800/450', NULL, 'https://music.msu.ac.th/facilities', NULL, 'อาคารวิทยาลัยดุริยางคศิลป์ มมส', '0', '1', '1', '2026-10-22 15:36:22');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('7', 'services', 'ระบบจองห้องซ้อมดนตรี และบริการยืมคืนเครื่องดนตรี', 'Practice Room Booking & Instrument Loan Services', '琴房预约与乐器借还服务', 'นิสิตสามารถจองห้องซ้อมเดี่ยว ห้องซ้อมวง และขอยืมเครื่องดนตรีผ่านระบบ e-Office ได้ตลอด 24 ชั่วโมง พร้อมระบบแจ้งเตือนผ่าน Telegram/LINE', 'Students can book individual practice rooms, ensemble rooms, and borrow instruments 24/7 via the e-Office portal.', '学生可通过学院 e-Office 系统全天候在线预约单人琴房、合奏室及借还乐器。', 'https://picsum.photos/id/1070/800/450', NULL, 'http://localhost/music-e-office/modules/practice_rooms/', NULL, 'เคาน์เตอร์บริการโสตฯ ชั้น 1', '0', '1', '0', '2026-10-22 14:56:56');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('8', 'achievements', 'ผลงานและความสำเร็จระดับชาติและนานาชาติ', 'National & International Awards and Achievements', '国家与国际级获奖成果', 'นิสิตและวงดนตรีวิทยาลัยดุริยางคศิลป์ มมส คว้าถ้วยพระราชทานและการแข่งขันดนตรีระดับนานาชาติ ตอกย้ำความเป็นเลิศด้านดนตรีอย่างต่อเนื่อง', 'Celebrating prestigious royal trophies and international competition victories won by our students and faculty ensembles.', '热烈庆祝音乐学院师生及乐团在各项国家级和国际音乐赛事中荣获最高奖项与殊荣。', 'https://picsum.photos/id/1058/800/450', NULL, 'https://music.msu.ac.th/achievements', NULL, 'หอเกียรติยศ ชั้น 1', '0', '1', '1', '2026-10-26 14:01:57');
