INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('60', 'programs', 'ข้อมูลการรับสมัครนิสิตใหม่ วิทยาลัยดุริยางคศิลป์', 'Admissions & Applications - College of Music', '玛哈沙拉仁大学音乐学院 招生与报名指南', 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม เปิดรับสมัครนิสิตใหม่ระดับปริญญาตรี ปริญญาโท และปริญญาเอก\n• ระดับปริญญาตรี (ป.ตรี): รับสมัครผ่านระบบคัดเลือกกลาง TCAS / ระบบรับสมัครมหาวิทยาลัยมหาสารคาม https://admission.msu.ac.th/\n• ระดับบัณฑิตศึกษา (ป.โท - ป.เอก): รับสมัครผ่านบัณฑิตวิทยาลัย มหาวิทยาลัยมหาสารคาม https://gradis.msu.ac.th/admission/\nเปิดรับทั้งภาคปกติและภาคพิเศษ สอบถามข้อมูลเพิ่มเติมได้ที่ สำนักงานวิชาการ อาคารวิทยาลัยดุริยางคศิลป์ โทร. 043-754385 หรือเว็บไซต์ https://music.msu.ac.th/', 'College of Music, Mahasarakham University welcomes new applicants for Undergraduate, Master\'s, and Doctoral degree programs.\n• Undergraduate (Bachelor\'s): Apply via TCAS / MSU Admission portal at https://admission.msu.ac.th/\n• Graduate (Master\'s & Ph.D.): Apply via MSU Graduate School at https://gradis.msu.ac.th/admission/\nFor inquiries, please contact Academic Affairs Office, College of Music Building, Tel: 043-754385 or visit https://music.msu.ac.th/', '玛哈沙拉仁大学音乐学院现面向海内外招收学士（本科）、硕士、博士研究生新生。\n• 本科学位课程：通过泰国大学集中录取系统 TCAS 及玛哈沙拉仁大学招生网申请（https://admission.msu.ac.th/）\n• 研究生学位课程（硕士/博士）：通过玛哈沙拉仁大学研究生院申请（https://gradis.msu.ac.th/admission/）\n详情咨询请联系学院学术教务处（音乐学院大楼），电话：043-754385，官网：https://music.msu.ac.th/', 'uploads/pr/programs/bed_degree_2569.jpg', NULL, 'https://admission.msu.ac.th/', NULL, 'สำนักงานวิชาการ อาคารวิทยาลัยดุริยางคศิลป์', '1', '1', '3', '2026-10-26 14:29:22');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('61', 'programs', 'หลักสูตรดุริยางคศาสตรบัณฑิต (ดศ.บ.) 4 ปี', 'Bachelor of Music Program (B.M.) 4-Year', '音乐学士学位课程 (B.M. 4年制)', 'หลักสูตรดุริยางคศาสตรบัณฑิต (ดศ.บ.) หลักสูตร 4 ปี มุ่งเน้นผลิตบัณฑิตที่มีความเป็นเลิศทางด้านการปฏิบัติและการสร้างสรรค์ดนตรี แบ่งเป็น 3 กลุ่มวิชา ได้แก่:\n1. กลุ่มวิชาดนตรีพื้นบ้าน (Folk Music) - สืบสาน พัฒนา และสร้างสรรค์ดนตรีพื้นบ้านอีสานสู่ระดับสากล\n2. กลุ่มวิชาดนตรีไทย (Thai Music) - เชี่ยวชาญทักษะปฏิบัติและการบรรเลงดนตรีไทยมาตรฐาน\n3. กลุ่มวิชาดนตรีตะวันตก (Western Music) - Classic, Contemporary, Jazz และการประพันธ์เพลง\n\nเปิดรับผู้สำเร็จการศึกษาระดับมัธยมศึกษาตอนปลาย (ม.6) หรือเทียบเท่า\nดาวน์โหลดเอกสารเล่มหลักสูตร: https://music.msu.ac.th/wp-content/uploads/2026/mb66.pdf\nสมัครเรียน: https://admission.msu.ac.th/', 'Bachelor of Music Program (B.M.) 4-year degree focuses on practical performance excellence and music creativity across 3 specialized concentrations:\n1. Folk Music (Isan Folk Music) - Preserving and elevating Northeast Thai folk music to the international stage\n2. Thai Classical Music - In-depth mastery of traditional Thai musical performance and theory\n3. Western Music - Classical, Contemporary, Jazz performance and Composition\n\nOpen for high school graduates (Grade 12 / M.6 or equivalent).\nCurriculum Details: https://music.msu.ac.th/wp-content/uploads/2026/mb66.pdf\nApply online: https://admission.msu.ac.th/', '音乐学士学位课程 (B.M.) 为4年制全日制本科，致力于培养具备卓越演奏演唱技能与音乐创新能力的专业人才，设有三大专业方向：\n1. 民间音乐方向 (Folk Music)：传承、发展与创新依善传统民间音乐，迈向国际舞台\n2. 泰国传统音乐方向 (Thai Music)：系统研习与精通泰国传统古典器乐与乐理\n3. 西洋音乐方向 (Western Music)：古典器乐/声乐、现代音乐、爵士乐及音乐创作\n\n招收高中毕业（中六）或同等学力学生。\n完整课程方案：https://music.msu.ac.th/wp-content/uploads/2026/mb66.pdf\n报名申请：https://admission.msu.ac.th/', 'uploads/pr/programs/bm_degree.jpg', NULL, 'https://music.msu.ac.th/wp-content/uploads/2026/mb66.pdf', NULL, 'ภาควิชาดุริยางคศิลป์ อาคารวิทยาลัยดุริยางคศิลป์', '2', '1', '2', '2026-10-26 14:11:59');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('62', 'programs', 'หลักสูตรการศึกษาบัณฑิต สาขาวิชาดนตรีศึกษา (กศ.บ. 4 ปี)', 'Bachelor of Education Program in Music Education (B.Ed. 4-Year)', '音乐教育学士学位课程 (B.Ed. 4年制)', 'หลักสูตรการศึกษาบัณฑิต สาขาวิชาดนตรีศึกษา (4 ปี) (หลักสูตร พ.ศ. 2569 และ 2564) มุ่งเน้นผลิตครูดนตรีมืออาชีพที่มีจิตวิญญาณความเป็นครู มีสมรรถนะการสอนดนตรีและทักษะปฏิบัติการดนตรีที่โดดเด่น แบ่งเป็น 3 กลุ่มวิชา:\n1. กลุ่มวิชาดนตรีพื้นบ้าน (Folk Music)\n2. กลุ่มวิชาดนตรีไทย (Thai Music)\n3. กลุ่มวิชาดนตรีตะวันตก (Western Music)\n\nสำเร็จการศึกษาได้รับใบอนุญาตประกอบวิชาชีพครู พร้อมจัดการเรียนการสอนและกิจกรรมดนตรีในสถานศึกษาทุกระดับ\nดาวน์โหลดเล่มหลักสูตร 2569: https://music.msu.ac.th/wp-content/uploads/2026/edu2569.pdf\nดาวน์โหลดเล่มหลักสูตร 2564: https://music.msu.ac.th/wp-content/uploads/2026/edu64.pdf\nสมัครเรียน: https://admission.msu.ac.th/', 'Bachelor of Education Program in Music Education (B.Ed. 4-Year) (Curriculum 2026 & 2021) prepares certified, innovative music educators with strong pedagogical expertise and performance musicianship across 3 study tracks:\n1. Folk Music Track\n2. Thai Classical Music Track\n3. Western Music Track\n\nGraduates receive teacher professional license, qualified to teach music at primary, secondary, and tertiary levels.\nCurriculum 2026: https://music.msu.ac.th/wp-content/uploads/2026/edu2569.pdf\nCurriculum 2021: https://music.msu.ac.th/wp-content/uploads/2026/edu64.pdf\nApply online: https://admission.msu.ac.th/', '音乐教育学士学位课程（B.Ed. 4年制，2026版与2021版大纲）旨在培养具有高尚师德、扎实音乐技能与优秀教学能力的专业音乐教师，设有三大专修方向：\n1. 民间音乐方向 (Folk Music)\n2. 泰国传统音乐方向 (Thai Music)\n3. 西洋音乐方向 (Western Music)\n\n毕业生具备教师专业执业资格，胜任各级中小学及教育机构音乐教学与活动指导。\n2026版教学大纲：https://music.msu.ac.th/wp-content/uploads/2026/edu2569.pdf\n2021版教学大纲：https://music.msu.ac.th/wp-content/uploads/2026/edu64.pdf\n报名网址：https://admission.msu.ac.th/', 'uploads/pr/programs/bed_degree_2564.jpg', NULL, 'https://music.msu.ac.th/wp-content/uploads/2026/edu2569.pdf', NULL, 'ภาควิชาดนตรีศึกษา อาคารวิทยาลัยดุริยางคศิลป์', '3', '1', '1', '2026-10-26 14:07:44');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('63', 'programs', 'หลักสูตรดุริยางคศาสตรมหาบัณฑิต (ดศ.ม.)', 'Master of Music Program (M.M.)', '音乐硕士学位课程 (Master of Music - M.M.)', 'หลักสูตรปริญญาดุริยางคศาสตรมหาบัณฑิต (ดศ.ม.) ระดับปริญญาโท มุ่งเน้นการสร้างองค์ความรู้ การวิจัย และความเป็นเลิศทางวิชาชีพดนตรีขั้นสูง แบ่งเป็น 7 กลุ่มวิชาเอก:\n1. กลุ่มวิชาเอกดนตรีวิทยา (Musicology)\n2. กลุ่มวิชาเอกดนตรีศึกษา (Music Education)\n3. กลุ่มวิชาเอกดนตรีพื้นบ้าน (Folk Music)\n4. กลุ่มวิชาเอกหมอลำ (Mor lam Performing Arts)\n5. กลุ่มวิชาเอกการจัดการดนตรีและศิลปะการแสดง (Music Management and Performing Arts)\n6. กลุ่มวิชาเอกบริหารธุรกิจดนตรีและเทคโนโลยีดนตรี (Music Business Administration and Music Technology)\n7. กลุ่มวิชาเอกการประพันธ์เพลง (Music Composition)\n\nโครงสร้างหลักสูตร:\n• แผน ก แบบ ก 1: วิจัยทำวิทยานิพนธ์อย่างเดียว ไม่น้อยกว่า 36 หน่วยกิต\n• แผน ก แบบ ก 2: ศึกษากระบวนวิชาไม่น้อยกว่า 12 หน่วยกิต และทำวิทยานิพนธ์ไม่น้อยกว่า 12 หน่วยกิต\n• แผน ข: ศึกษากระบวนวิชา และค้นคว้าอิสระ (Independent Study) ไม่น้อยกว่า 3-6 หน่วยกิต\nดาวน์โหลดรายละเอียด: https://music.msu.ac.th/wp-content/uploads/2026/mm66.docx\nสมัครเรียนบัณฑิตศึกษา: https://gradis.msu.ac.th/admission/', 'Master of Music Program (M.M.) provides advanced academic scholarship, creative research, and professional musicianship with 7 specialized majors:\n1. Musicology\n2. Music Education\n3. Folk Music\n4. Mor lam Performing Arts\n5. Music Management and Performing Arts\n6. Music Business Administration and Music Technology\n7. Music Composition\n\nStudy Plans:\n• Plan A (Type A1): Pure thesis research (at least 36 credits)\n• Plan A (Type A2): Coursework (min. 12 credits) + Thesis (min. 12 credits)\n• Plan B: Coursework + Independent Study (3-6 credits)\nCurriculum file: https://music.msu.ac.th/wp-content/uploads/2026/mm66.docx\nGraduate Admission: https://gradis.msu.ac.th/admission/', '音乐硕士学位课程（M.M.）注重深化学术研究、音乐创作与高端专业实践，设有7大专业研究方向：\n1. 音乐学 (Musicology)\n2. 音乐教育 (Music Education)\n3. 民间音乐 (Folk Music)\n4. 莫兰表演艺术 (Mor lam Performing Arts)\n5. 音乐与表演艺术管理 (Music Management and Performing Arts)\n6. 音乐商务管理与音乐科技 (Music Business Administration & Music Tech)\n7. 音乐作曲 (Music Composition)\n\n培养方案与学制计划：\n• 方案A（A1型）：纯论文研究型，学位论文不少于36学分\n• 方案A（A2型）：课程学习（不少于12学分）+ 硕士学位论文（不少于12学分）\n• 方案B：课程学习 + 独立课题研究报告（3-6学分）\n课程文档下载：https://music.msu.ac.th/wp-content/uploads/2026/mm66.docx\n研究生招生网：https://gradis.msu.ac.th/admission/', 'uploads/pr/programs/mm_degree.jpg', NULL, 'https://music.msu.ac.th/wp-content/uploads/2026/mm66.docx', NULL, 'สำนักงานวิชาการบัณฑิตศึกษา อาคารวิทยาลัยดุริยางคศิลป์', '4', '1', '1', '2026-10-26 14:07:47');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('64', 'programs', 'หลักสูตรการศึกษามหาบัณฑิต สาขาวิชาดนตรีศึกษา (กศ.ม.)', 'Master of Education Program in Music Education (M.Ed.)', '音乐教育教育学硕士学位课程 (M.Ed.)', 'หลักสูตรการศึกษามหาบัณฑิต สาขาวิชาดนตรีศึกษา (กศ.ม.) / Master of Education Program in Music Education\nชื่อย่อ: กศ.ม. (ดนตรีศึกษา) / M.Ed. (Music Education)\nมุ่งผลิตมหาบัณฑิตด้านดนตรีศึกษาที่มีความเชี่ยวชาญด้านหลักสูตร การสอน การวิจัยทางการศึกษาดนตรี นวัตกรรมการสอนดนตรีในศตวรรษที่ 21 และการพัฒนาศักยภาพผู้เรียนดนตรีอย่างรอบด้าน\n\nเหมาะสำหรับครู อาจารย์ บุคลากรทางการศึกษา และผู้สนใจพัฒนาความเป็นเลิศด้านการจัดการเรียนรู้วิชาดนตรี\nดาวน์โหลดเอกสารหลักสูตร: https://music.msu.ac.th/wp-content/uploads/2026/master_edu67.pdf\nสมัครเรียนบัณฑิตศึกษา: https://gradis.msu.ac.th/admission/', 'Master of Education Program in Music Education (M.Ed.)\nDegree abbreviation: M.Ed. (Music Education)\nDesigned for music educators, researchers, and administrators aiming to master advanced music pedagogy, 21st-century music teaching innovations, curriculum design, and educational research.\n\nOpen for teachers, educational personnel, and professionals passionate about music education excellence.\nCurriculum Details: https://music.msu.ac.th/wp-content/uploads/2026/master_edu67.pdf\nApply via Graduate School: https://gradis.msu.ac.th/admission/', '音乐教育硕士学位课程 (Master of Education in Music Education - M.Ed.)\n学位简称：M.Ed. (Music Education)\n致力于培养深谙现代音乐教育学理论、具备21世纪创新教学法、课程设计与教育科研能力的音乐教育骨干力量。\n\n面向在职音乐教师、学校教育工作者及致力于音乐教育教学研究的专业人士。\n完整课程方案：https://music.msu.ac.th/wp-content/uploads/2026/master_edu67.pdf\n研究生报名：https://gradis.msu.ac.th/admission/', 'uploads/pr/programs/med_degree.jpg', NULL, 'https://music.msu.ac.th/wp-content/uploads/2026/master_edu67.pdf', NULL, 'ภาควิชาดนตรีศึกษา อาคารวิทยาลัยดุริยางคศิลป์', '5', '1', '1', '2026-10-26 14:10:23');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('65', 'programs', 'หลักสูตรปรัชญาดุษฎีบัณฑิต สาขาวิชาดุริยางคศิลป์ (ปร.ด.)', 'Doctor of Philosophy Program in Music (Ph.D.)', '音乐哲学博士学位课程 (Doctor of Philosophy in Music - Ph.D.)', 'หลักสูตรปริญญาปรัชญาดุษฎีบัณฑิต สาขาวิชาดุริยางคศิลป์ (ปร.ด.) / Doctor of Philosophy Program in Music มุ่งสร้างดุษฎีบัณฑิตนักวิจัยชั้นนำ ผู้สร้างสรรค์องค์ความรู้ใหม่ทางดุริยางคศิลป์ในระดับสากล แบ่งเป็น 3 แขนงวิชา:\n1. แขนงวิชาดนตรีวิทยา (Musicology)\n2. แขนงวิชาดนตรีศึกษา (Music Education)\n3. แขนงวิชาการบริหารจัดการทางดนตรี (Music Administration)\n\nรูปแบบการศึกษาแบ่งเป็น 2 แบบ:\n• แบบ 1 (เน้นการวิจัยบริสุทธิ์เพื่อสร้างองค์ความรู้ใหม่):\n  - แบบ 1.1: ผู้สำเร็จปริญญาโท ทำดุษฎีนิพนธ์ไม่น้อยกว่า 48 หน่วยกิต\n  - แบบ 1.2: ผู้สำเร็จปริญญาตรี (เกียรตินิยม) ทำดุษฎีนิพนธ์ไม่น้อยกว่า 72 หน่วยกิต\n• แบบ 2 (วิจัยพร้อมศึกษากระบวนวิชาเพิ่มเติม):\n  - แบบ 2.1: ผู้สำเร็จปริญญาโท ทำดุษฎีนิพนธ์ไม่น้อยกว่า 36 หน่วยกิต และศึกษารายวิชาไม่น้อยกว่า 12 หน่วยกิต\n  - แบบ 2.2: ผู้สำเร็จปริญญาตรี ทำดุษฎีนิพนธ์ไม่น้อยกว่า 48 หน่วยกิต และศึกษารายวิชาไม่น้อยกว่า 24 หน่วยกิต\nดาวน์โหลดรายละเอียด: https://music.msu.ac.th/wp-content/uploads/2026/phd66.docx\nสมัครเรียนบัณฑิตศึกษา: https://gradis.msu.ac.th/admission/', 'Doctor of Philosophy Program in Music (Ph.D.) cultivates world-class musical scholars, pioneering researchers, and academic leaders across 3 key academic branches:\n1. Musicology\n2. Music Education\n3. Music Administration\n\nStudy Options:\n• Type 1 (Pure Research):\n  - Type 1.1: Master\'s degree entrants - Dissertation min. 48 credits\n  - Type 1.2: Bachelor\'s with honors entrants - Dissertation min. 72 credits\n• Type 2 (Coursework & Research):\n  - Type 2.1: Master\'s degree entrants - Dissertation min. 36 credits + Coursework min. 12 credits\n  - Type 2.2: Bachelor\'s degree entrants - Dissertation min. 48 credits + Coursework min. 24 credits\nCurriculum document: https://music.msu.ac.th/wp-content/uploads/2026/phd66.docx\nGraduate School Admission: https://gradis.msu.ac.th/admission/', '音乐哲学博士学位课程（Ph.D.）致力于培养高水平音乐学术研究领军人才与高等学府学者，设有3大学术专业分支：\n1. 音乐学方向 (Musicology)\n2. 音乐教育方向 (Music Education)\n3. 音乐行政与管理方向 (Music Administration)\n\n培养类型与学分要求：\n• 模式 1（纯学术研究型）：\n  - 模式 1.1（硕士起点）：博士学位论文不少于48学分\n  - 模式 1.2（本科学士优秀荣誉起点）：博士学位论文不少于72学分\n• 模式 2（课程学习 + 课题研究型）：\n  - 模式 2.1（硕士起点）：博士学位论文不少于36学分 + 研究生课程不少于12学分\n  - 模式 2.2（本科起点）：博士学位论文不少于48学分 + 研究生课程不少于24学分\n大纲文档下载：https://music.msu.ac.th/wp-content/uploads/2026/phd66.docx\n研究生招生网：https://gradis.msu.ac.th/admission/', 'uploads/pr/programs/phd_degree.jpg', NULL, 'https://music.msu.ac.th/wp-content/uploads/2026/phd66.docx', NULL, 'สำนักงานวิชาการบัณฑิตศึกษา อาคารวิทยาลัยดุริยางคศิลป์', '6', '1', '2', '2026-10-26 14:10:36');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('66', 'about', 'ประวัติความเป็นมา วิทยาลัยดุริยางคศิลป์ มมส.', 'History & Background - College of Music', '玛哈沙拉仁大学音乐学院 发展历史与沿革', '“วิทยาลัยดุริยางคศิลป์” เป็นโครงการตามแผนปฏิบัติราชการ 4 ปี พ.ศ. 2550–2554 (ได้รับอนุมัติจากสภามหาวิทยาลัย เมื่อวันที่ 26 กันยายน 2551) เดิมเป็นสาขาวิชาดุริยางคศิลป์ สังกัดคณะศิลปกรรมศาสตร์\n\nและในปี พ.ศ. 2550 สาขาวิชาดุริยางคศิลป์ได้แยกการบริหารออกมาจากคณะศิลปกรรมศาสตร์ เป็นโครงการจัดตั้งวิทยาลัยดุริยางคศิลป์ ซึ่งมีหน้าที่หลักในการจัดการเรียนการสอนให้แก่บุคคลที่สนใจศึกษาในสาขาวิชาด้านดนตรี\n• พ.ศ. 2540: เปิดหลักสูตรศิลปกรรมศาสตรบัณฑิต สาขาวิชาดุริยางคศิลป์\n• พ.ศ. 2549: เปิดหลักสูตรศิลปกรรมศาสตรมหาบัณฑิต สาขาวิชาดุริยางคศิลป์\n• พ.ศ. 2550: ร่วมมือกับโรงเรียนสาธิต มหาวิทยาลัยมหาสารคาม จัดการเรียนการสอนหลักสูตรเตรียมอุดมดนตรี\n• พ.ศ. 2551: เปิดหลักสูตรปรัชญาดุษฎีบัณฑิต สาขาวิชาดุริยางคศิลป์\n\nวิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม ได้รับประกาศให้จัดตั้งเป็นวิทยาลัยดุริยางคศิลป์ ตามความในมาตรา 4 แห่งพระราชบัญญัติการบริหารส่วนงานภายในของสถาบันอุดมศึกษา พ.ศ. 2550 และประกาศคณะกรรมการการอุดมศึกษา เรื่องหลักเกณฑ์การจัดตั้งส่วนงานภายในของสถาบันอุดมศึกษา ในการประชุมสภามหาวิทยาลัยมหาสารคาม ครั้งที่ 9/2551 เมื่อวันที่ 26 กันยายน 2551 จึงมีมติอนุมัติให้จัดตั้งวิทยาลัยดุริยางคศิลป์เป็นส่วนงานภายในของสถาบันอุดมศึกษา และมีฐานะเทียบเท่าคณะ มีชื่อเรียกเป็นภาษาอังกฤษว่า “College of Music”', 'The \"College of Music\" originated from the 4-Year Action Plan (2007–2011), approved by the University Council on September 26, 2008. Formerly the Department of Music under the Faculty of Fine and Applied Arts, it separated management in 2007 to establish the College of Music Founding Project.\n• 1997: Launched Bachelor of Fine Arts in Music\n• 2006: Launched Master of Fine Arts in Music\n• 2007: Partnered with Mahasarakham University Demonstration School for Pre-College Music Education\n• 2008: Launched Doctor of Philosophy Program in Music\n\nUnder Section 4 of the Internal Higher Education Administration Act B.E. 2550 (2007), the MSU University Council formally declared the establishment of the College of Music on September 26, 2008, operating with full faculty-equivalent status.', '玛哈沙拉仁大学“音乐学院”（College of Music）起源于大学四年工作规划（2007-2011年），于2008年9月26日获大学理事会批准正式成立。原为美术与应用艺术学院音乐学系，2007年独立筹建音乐学院设立项目。\n• 1997年：设立音乐学学士学位课程\n• 2006年：设立音乐学硕士学位课程\n• 2007年：与玛哈沙拉仁大学附属示范中学合作开展大学预科音乐教学\n• 2008年：设立音乐学哲学博士学位课程\n\n依据泰国《高等教育机构内部管理条例》（佛历2550年）第4条规定，玛哈沙拉仁大学理事会于2008年9月26日第9/2551次会议上正式决议设立音乐学院，拥有等同于大学学院（Faculty）的正式法律与行政地位。', 'uploads/pr/about/hall_music_msu.jpg', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'อาคารวิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม', '1', '1', '2', '2026-10-26 14:48:21');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('67', 'about', 'ตราสัญลักษณ์และความหมายโลโก้ (MusicMSU 2025)', 'Official Emblem & Symbolism (MusicMSU 2025)', '玛哈沙拉仁大学音乐学院 院徽与象征意义', 'ตราสัญลักษณ์ประจำวิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม (MusicMSU 2025) ประกอบด้วยความหมายอันทรงคุณค่าที่สะท้อนถึงศาสตร์และศิลป์ทางดนตรี:\n• รูปโล่: สื่อถึงความมั่นคง เกียรติศักดิ์ และการปกป้องคุณค่าทางดนตรีของชาติ เปรียบเหมือนหัวใจขององค์กรที่รวมทั้งศาสตร์และศิลป์ไว้ในหนึ่งเดียว [Unity (U) / SO5]\n• ใบลอเรล: สัญลักษณ์แห่งเกียรติยศ ความสำเร็จ และความภาคภูมิใจในศิลปะดนตรี เปรียบเสมือนมงกุฎแห่งปัญญาและชัยชนะของผู้เรียนและผู้สอน [Mastery (M) / SO1, SO2]\n• สีพื้นโล่: สีทอง หมายถึงความรุ่งเรือง ความงดงาม และความมั่นคง; สีม่วงอมฟ้า เป็นสีประจำวิทยาลัย หมายถึงปัญญา ศิลปะ และความลุ่มลึกในสุนทรียศาสตร์ [Artistry (A), Nation (N)]\n• พระธาตุนาดูน: สัญลักษณ์ประจำจังหวัดมหาสารคาม สื่อถึงรากเหง้าแห่งศิลปวัฒนธรรมอีสาน และพลังศรัทธาทางจิตวิญญาณของชุมชน [Nation (N) / SO4]\n• แคน: เครื่องดนตรีพื้นบ้านอีสาน แทนเสียงแห่งชีวิต และความเชื่อของชุมชน เป็นหัวใจของจิตสำนึกดนตรีในถิ่นอีสาน [Nation (N) / SO3, SO4]\n• กุญแจซอล: ตัวแทนของความเป็นสากล ความงดงามของเสียง และการเรียนรู้ที่ไร้พรมแดน [Artistry (A) / SO1, SO2]\n• คีย์เปียโน: แทนระบบการเรียนการสอนดนตรีอย่างมืออาชีพ เป็นพื้นฐานความเชี่ยวชาญในศาสตร์ดนตรีสากลและเทคโนโลยี [Mastery (M) / SO1]\n• ฆ้องวงใหญ่: เครื่องดนตรีไทยที่สื่อถึงความยิ่งใหญ่ ความสง่างาม และความสามัคคีในวงการดนตรีไทยและพื้นบ้าน [Unity (U) / SO3, SO4]', 'The official emblem of the College of Music (MusicMSU 2025) combines rich cultural heritage and international musicianship:\n• The Shield: Represents dignity, stability, and cultural preservation, unifying music arts and sciences [Unity (U) / SO5].\n• Golden Laurel Wreath: Symbolizes academic triumph, honor, and musical mastery for students and faculty [Mastery (M) / SO1, SO2].\n• Shield Colors: Royal Gold denotes prosperity, grace, and stability; Violet-Blue (college color) symbolizes wisdom, art, and aesthetic depth [Artistry (A), Nation (N)].\n• Phra That Na Dun: The revered sacred stupa of Mahasarakham, honoring northeastern Isan spiritual roots [Nation (N) / SO4].\n• Isan Khaen (Reed Mouth Organ): Voice of life and communal spirit, the heart of Isan musical consciousness [Nation (N) / SO3, SO4].\n• Treble Clef (G Clef): Represents global musical universality, melodious beauty, and borderless learning [Artistry (A) / SO1, SO2].\n• Piano Keys: Professional Western music pedagogy, foundation of performance and music technology [Mastery (M) / SO1].\n• Thai Khong Wong Yai (Gong Circle): Majesty, harmony, and classical Thai musical unity [Unity (U) / SO3, SO4].', '玛哈沙拉仁大学音乐学院官方院徽（MusicMSU 2025）融合泰国民族瑰宝与国际音乐精粹：\n• 盾牌徽章：象征尊严坚毅、保卫国家音乐瑰宝，凝聚艺术与学术于一体 [Unity (U) / SO5]\n• 金色月桂花环：象征音乐学术造诣、荣光成就与胜利之冠 [Mastery (M) / SO1, SO2]\n• 盾底色彩：金色代表繁荣昌盛与坚定稳固；蓝紫色（学院标志色）代表智慧、艺术创造与深沉美学 [Artistry (A), Nation (N)]\n• 帕塔那敦佛塔：玛哈沙拉仁府的神圣象征，根植于依善本土文化与精神力量 [Nation (N) / SO4]\n• 依善芦笙（Khaen）：东北民间音乐之魂，象征生命律动与乡土信仰 [Nation (N) / SO3, SO4]\n• 高音谱号（G谱号）：象征国际视野、声音美学与无国界探索 [Artistry (A) / SO1, SO2]\n• 钢琴黑白键：代表专业现代音乐教学体系、演奏技能与音乐科技 [Mastery (M) / SO1]\n• 泰国围锣（Khong Wong Yai）：代表泰国古典音乐之恢弘庄严与团队同心 [Unity (U) / SO3, SO4]', 'uploads/pr/about/MusicMSU-logo2025.png', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม', '2', '1', '1', '2026-10-26 14:18:25');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('68', 'about', 'ปรัชญา วิสัยทัศน์ พันธกิจ และสมรรถนะหลัก (IPOP)', 'Philosophy, Vision, Mission & Core Competency (IPOP)', '办学理念、发展愿景、核心使命与核心竞争力 (IPOP)', 'ปรัชญา (Philosophy)\n“ดุริยางคศิลป์ สุนทรียศาสตร์แห่งแผ่นดิน” (Music: The Aesthetics of the Land)\n\nวิสัยทัศน์ (Vision)\n“เป็นวิทยาลัยดนตรีชั้นนำสำหรับทุกคน” (Leading College of Music for Everyone)\n\nพันธกิจ 4 ด้าน (Missions)\n1. ผลิตบัณฑิตทางดนตรีที่มีคุณภาพทั้งด้านความรู้และทักษะด้านดนตรี\n2. พัฒนาระบบการเรียนการสอนที่เน้นประสิทธิผลผ่านระบบการบริหารจัดการที่ดีที่มีประสิทธิภาพ\n3. ส่งเสริมการวิจัยและงานสร้างสรรค์ทางดนตรีเพื่อพัฒนาความเป็นเลิศทางวิชาการทั้งในระดับภูมิภาคและระดับนานาชาติ\n4. สร้างบทบาทในฐานะผู้บริการแก่สังคม อนุรักษ์ พัฒนาและถ่ายทอดองค์ความรู้ทางดนตรีให้เกิดผลทางวิชาการและเชิงธุรกิจ\n\nสมรรถนะหลักขององค์กร (Core Competency)\nIPOP: เป็นผู้นำด้านวิชาการทางดนตรีพื้นบ้านอีสาน และการให้บริการทางวิชาการด้านดนตรีที่มากที่สุดในภาคตะวันออกเฉียงเหนือ', 'Philosophy:\n\"Music: The Aesthetics of the Land\"\n\nVision:\n\"A Leading College of Music for Everyone\"\n\nCore Missions:\n1. Graduate Quality: Produce distinguished music graduates with superior musical proficiency, theory, and professional skills.\n2. Effective Pedagogy: Cultivate an effective, outcome-based educational ecosystem driven by good governance and efficient management.\n3. Research & Creative Excellence: Promote high-impact music research and artistic creation to achieve regional and international recognition.\n4. Academic & Community Services: Serve society through music knowledge dissemination, cultural preservation, and creative enterprise development.\n\nCore Competency (IPOP):\nNortheastern Isan Folk Music Academic Leadership and the Largest Music Community Service Provider in Northeast Thailand.', '办学理念（Philosophy）：\n“音乐艺术：大地之美学”（Music: The Aesthetics of the Land）\n\n学院愿景（Vision）：\n“成为面向所有人的卓越音乐学府”（Leading College of Music for Everyone）\n\n四大核心使命（Missions）：\n1. 培养卓越音乐英才：塑造具备深厚专业知识、卓越音乐技能与职业道德的复合型人才。\n2. 建设高效教学体系：通过科学管理与高效运作，打造重实效的现代化音乐教育模式。\n3. 推动科研创作攀登：深耕音乐学术科研与艺术创作，迈向区域及国际学术卓越。\n4. 赋能社会服务传承：弘扬与保护民族音乐文化，推动音乐知识传播与文化创意产业转化。\n\n核心竞争力（IPOP）：\n泰国东北部民间音乐学术领航者，以及东北地区覆盖面最广的专业音乐社会服务机构。', 'uploads/pr/about/about_building_5.jpg', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม', '3', '1', '2', '2026-10-26 14:48:26');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('69', 'about', 'ค่านิยมองค์กร MUAN (ม่วน)', 'Core Values: MUAN', '学院核心价值观：MUAN（乐/欢愉）', 'ค่านิยมองค์กร MUAN (ม่วน)\n“ม่วน • ดนตรีเพื่อทุกคน • ระบบเพื่อความเป็นเลิศ”\n| MASTERY • UNITY • ARTISTRY • NATION |\n\n• M - Mastery (เชี่ยวชาญ)\nมุ่งมั่นพัฒนาความรู้และทักษะวิชาชีพดนตรีให้ลึกซึ้ง และมีมาตรฐานระดับสากล มุ่งสู่ความเป็นเลิศทางวิชาการและการปฏิบัติ\n\n• U - Unity (สามัคคี)\nทำงานร่วมกันด้วยความเข้าใจ และสนับสนุนกันในทุกระดับ สร้างพลังของทีมเพื่อความเป็นเลิศและความผูกพันในองค์กร\n\n• A - Artistry (สร้างสรรค์)\nความงามของเสียงและการสร้างสรรค์ ใช้ศิลปะและความคิดสร้างสรรค์ ขับเคลื่อนดนตรีให้เกิดพลังบวกแก่สังคมและวัฒนธรรม\n\n• N - Nation (ภูมิปัญญา / สืบสาน รากเหง้า สู่สากล)\nอนุรักษ์ดนตรีพื้นบ้านและวัฒนธรรมไทย พร้อมพัฒนาให้ก้าวสู่เวทีโลก ด้วยความภาคภูมิใจในรากเหง้า และวิสัยทัศน์ระดับนานาชาติ', 'Core Values: MUAN (Joyful & Harmonious)\n\"Joyful Music for Everyone • Systematic Excellence\"\n| MASTERY • UNITY • ARTISTRY • NATION |\n\n• M - Mastery: Professional Expertise\nDedicated to deepening musical knowledge, rigorous skills, and global educational standards.\n\n• U - Unity: Cohesion & Teamwork\nWorking collaboratively with mutual empathy, interdisciplinary synergy, and organizational solidarity.\n\n• A - Artistry: Creative Sound & Aesthetics\nHarnessing artistic imagination, innovation, and musical aesthetics to deliver positive social impact.\n\n• N - Nation: Cultural Heritage to Global Stage\nPreserving traditional Thai and Isan musical heritage, elevating indigenous wisdom to the global international arena.', '学院核心价值观：MUAN（泰东北方言意为：欢愉、乐享）\n“乐享音乐 • 惠及大众 • 卓越体系”\n| MASTERY（精深） • UNITY（同心） • ARTISTRY（创艺） • NATION（根脉） |\n\n• M - Mastery（精益求精）：\n矢志深耕音乐学术与演奏演唱技艺，对标国际水准，追求卓越造诣。\n\n• U - Unity（精诚团结）：\n包容协作、凝心聚力，跨学科协同发展，以团队智慧共筑学院辉煌。\n\n• A - Artistry（艺术创新）：\n追求声乐器乐极致之美，以艺术灵感与创新思维赋能社会文化生活。\n\n• N - Nation（根脉传承）：\n立足泰东北本土民间音乐瑰宝，怀抱文化自信，推动民族音乐迈向国际舞台。', 'uploads/pr/about/MusicMSU-F1.png', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม', '4', '1', '1', '2026-10-26 14:18:31');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('70', 'about', 'วัตถุประสงค์เชิงกลยุทธ์ 5 ประการ (SO 1 - SO 5)', 'Strategic Objectives (SO1 - SO5)', '五大战略目标 (SO1 - SO5)', 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม ขับเคลื่อนการดำเนินงานตามวัตถุประสงค์เชิงกลยุทธ์ 5 ด้าน (Strategic Objectives: SO 1 - SO 5) ได้แก่:\n\n• SO 1: จัดการศึกษาสอดคล้องกับความต้องการของสังคมโลก\nพัฒนานิสิตและหลักสูตรดนตรีทุกระดับให้มีทักษะศตวรรษที่ 21 ตอบสนองตลาดแรงงานสากลและอุตสาหกรรมดนตรีสมัยใหม่\n\n• SO 2: ผลิตงานวิจัย นวัตกรรม และงานสร้างสรรค์ เพื่อความเป็นเลิศในระดับนานาชาติ\nส่งเสริมคณาจารย์และนิสิตสร้างผลงานวิจัย นวัตกรรมทางดนตรี และผลงานสร้างสรรค์ที่ได้รับการยอมรับในเวทีระดับโลก\n\n• SO 3: ให้บริการวิชาการชุมชนและสังคม เพื่อนำไปสู่การพัฒนาอย่างยั่งยืน\nถ่ายทอดองค์ความรู้ทางดนตรีแก่เยาวชน ชุมชน และสังคม เสริมสร้างเศรษฐกิจสร้างสรรค์และคุณภาพชีวิต\n\n• SO 4: ทำนุบำรุงศิลปวัฒนธรรมด้านดนตรีให้มีความยั่งยืน และมีความโดดเด่นระดับนานาชาติ\nอนุรักษ์ สืบสาน และยกระดับดนตรีพื้นบ้านอีสานและดนตรีไทยสู่ระดับสากลอย่างยั่งยืน\n\n• SO 5: บริหารจัดการองค์กรสู่ความเป็นเลิศ (Smart Music College)\nพัฒนาระบบบริหารจัดการด้วยเทคโนโลยีดิจิทัล ธรรมาภิบาล และการบริหารตามเกณฑ์คุณภาพสู่ความเป็นเลิศ (EdPEx)', 'College of Music Strategic Objectives (SO1 - SO5):\n• SO 1 - Globally Responsive Education: Deliver contemporary music curricula that align with international standards and creative industries.\n• SO 2 - High-Impact Research & Creative Innovation: Produce world-class musical research, artistic works, and innovative productions.\n• SO 3 - Sustainable Community Engagement: Extend academic and musical services to empower local communities and promote creative economy.\n• SO 4 - Sustainable Cultural Stewardship: Safeguard, revitalize, and showcase traditional Thai and Isan music prominently on the global stage.\n• SO 5 - Organizational Excellence (Smart Music College): Modernize institutional governance through digital technology and EdPEx quality framework.', '玛哈沙拉仁大学音乐学院五大战略目标（SO1 - SO5）：\n• SO 1 - 顺应时代需求的现代音乐教育：革新课程结构，培养具备国际竞争力与适应数字音乐时代的精英人才。\n• SO 2 - 追求国际卓越的科研与艺术创作：产出高水平学术研究、发明创新及具有国际影响力的舞台艺术创作。\n• SO 3 - 赋能社会可持续发展的学术服务：开展社区普及教育与公益音乐惠民，以文化推动地方创意经济发展。\n• SO 4 - 卓越传承民族与本土音乐文化：深耕依善本土民间音乐与泰国古典音乐的保护、传承与国际化传播。\n• SO 5 - 迈向卓越的智慧学院建设（Smart Music College）：推进数字化治理，遵循EdPEx卓越绩效准则，提升行政效能。', 'uploads/pr/about/about_campus_2.jpg', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม', '5', '1', '0', '2026-10-26 14:17:48');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('71', 'about', 'โครงสร้างการแบ่งส่วนงานและการบริหารงานบุคคล', 'Organization & Management Structure', '组织机构与管理体系', 'โครงสร้างการบริหารงานบุคคลและองค์กร วิทยาลัยดุริยางคศิลป์ มหาวิทยาลัยมหาสารคาม:\n• อธิการบดีมหาวิทยาลัยมหาสารคาม\n  - คณะกรรมการประจำวิทยาลัยดุริยางคศิลป์\n  - คณบดีวิทยาลัยดุริยางคศิลป์\n    - ผู้ช่วยคณบดี\n    - รองคณบดีฝ่ายบริหาร\n    - รองคณบดีฝ่ายวิชาการ\n    - รองคณบดีฝ่ายพัฒนานิสิต\n    - รองคณบดีฝ่ายบริการวิชาการ\n\nการแบ่งส่วนงานภายใน:\n1. สำนักงานเลขานุการ\n   • กลุ่มงานบริหาร: งานบุคคล, งานประชุม, งานเลขานุการ, งานสารบรรณ, งานยานยนต์, งานอาคารสถานที่, งานวิเทศสัมพันธ์, งานโสตทัศนูปกรณ์, งานคอมพิวเตอร์และเทคโนโลยี, งานประชาสัมพันธ์และส่งเสริมภาพลักษณ์\n   • กลุ่มงานนโยบาย แผนและคลัง: งานพัสดุ, งานการเงินและบัญชี, งานนโยบายและแผน, งานงบประมาณ, งานอัตรากำลัง, งานความเสี่ยงและควบคุมภายใน, งานยุทธศาสตร์ กพร., EdPEx, งานจัดการความรู้\n   • กลุ่มงานวิชาการและพัฒนานิสิต: งานวิชาการ, งานประกันคุณภาพการศึกษาภายใน, งานพัฒนาและสวัสดิภาพนิสิต, งานวิจัยและวารสาร, งานศิษย์เก่าสัมพันธ์, งานทุนการศึกษา, งานบริการวิชาการ, งานทำนุบำรุงศิลปวัฒนธรรม\n2. ภาควิชา\n   • ภาควิชาดนตรีศึกษา: งานบริหารหลักสูตรและการจัดการเรียนการสอน, การให้คำปรึกษานิสิต\n   • ภาควิชาดุริยางคศาสตร์: งานบริหารหลักสูตรและการจัดการเรียนการสอน, การให้คำปรึกษานิสิต', 'College Organization & Management Structure:\n• President of Mahasarakham University\n  - College Committee Board\n  - Dean, College of Music\n    - Assistant to the Dean\n    - Associate Dean for Administration\n    - Associate Dean for Academic Affairs\n    - Associate Dean for Student Development\n    - Associate Dean for Academic Services\n\nDivisions & Units:\n1. Office of the Secretariat:\n   • Administration Unit: Personnel, Meetings, Secretarial, Correspondence, Vehicles, Facilities, International Relations, AV Equipment, IT, Public Relations & Branding.\n   • Policy, Planning & Finance Unit: Procurement, Finance & Accounting, Policy & Planning, Budgeting, Manpower, Risk Management, EdPEx, Knowledge Management.\n   • Academic & Student Development Unit: Academic Affairs, QA, Student Welfare, Research & Journal, Alumni, Scholarships, Academic Services, Arts & Culture.\n2. Academic Departments:\n   • Department of Music Education\n   • Department of Music Performance (College of Music)', '学院组织机构与管理体系：\n• 玛哈沙拉仁大学校长\n  - 音乐学院院务委员会\n  - 音乐学院院长\n    - 院长助理\n    - 行政副院长\n    - 教务学术副院长\n    - 学生发展副院长\n    - 社会服务与外联副院长\n\n内部部门与内设科室：\n1. 学院办公室（秘书处）：\n   • 综合行政组：人事档案、行政会议、文书公文、车辆调配、后勤场地、国际交流、影音设备、网络技术、宣传公关。\n   • 政策规划与财务组：物资采购、财务会计、政策规划、预算管理、编制核准、风险防控、EdPEx质量认证、知识管理。\n   • 教务与学生发展组：教务管理、教学评估、学生事务、科研与学报、校友联络、奖助学金、学术服务、文化传承。\n2. 教学系部：\n   • 音乐教育学系：教学管理与课程实施、导师咨询与学业辅导。\n   • 音乐表演学系：教学管理与课程实施、导师咨询与学业辅导。', 'uploads/pr/about/MusicMSU-F2.png', NULL, 'https://music.msu.ac.th/?page_id=164', NULL, 'สำนักงานเลขานุการ อาคารวิทยาลัยดุริยางคศิลป์', '6', '1', '1', '2026-10-26 14:48:30');
INSERT INTO `pr_kiosk_contents` (`content_id`, `category_key`, `title_th`, `title_en`, `title_cn`, `detail_th`, `detail_en`, `detail_cn`, `thumbnail_image`, `media_url`, `qr_link`, `event_date`, `location`, `sort_order`, `is_active`, `view_count`, `updated_at`) VALUES ('72', 'about', 'ข้อบังคับมหาวิทยาลัยมหาสารคาม ว่าด้วยการบริหารงาน วิทยาลัยดุริยางคศิลป์', 'MSU Regulations on the Administration of College of Music', '玛哈沙拉仁大学音乐学院 管理与运行规章（佛历2553年）', 'ข้อบังคับมหาวิทยาลัยมหาสารคาม ว่าด้วย การบริหารงานและการดำเนินงานของวิทยาลัยดุริยางคศิลป์ พ.ศ. 2553\n\nออกตามความในมาตรา 4 แห่งพระราชบัญญัติการบริหารส่วนงานภายในของสถาบันอุดมศึกษา พ.ศ. 2550 และมติสภามหาวิทยาลัยมหาสารคาม กำหนดอำนาจหน้าที่ การบริหารจัดการ โครงสร้างการดำเนินงานของคณะกรรมการประจำวิทยาลัย คณบดี และการบริหารงานวิชาการของวิทยาลัยดุริยางคศิลป์ ให้มีประสิทธิภาพ คล่องตัว และเป็นไปตามหลักธรรมาภิบาล\n\nแตะปุ่มด้านล่างเพื่อเปิดอ่านเอกสารข้อบังคับฉบับเต็มบนหน้าจอนี้ หรือสแกน QR Code เพื่อเปิดอ่านบนโทรศัพท์มือถือของคุณ\nเอกสารทางการ: https://music.msu.ac.th/wp-content/uploads/2024/12/ข้อบังคับปี2553.pdf', 'Mahasarakham University Regulations on the Administration and Operations of the College of Music B.E. 2553 (2010).\n\nEnacted under Section 4 of the Internal Higher Education Administration Act B.E. 2550 and approved by the MSU University Council, these regulations govern administrative authority, leadership duties of the Dean and College Board, academic operations, and institutional governance to ensure efficiency and excellence.\n\nTap the button below to view the official document directly on this screen, or scan the QR Code to read on your mobile device.\nOfficial Document: https://music.msu.ac.th/wp-content/uploads/2024/12/ข้อบังคับปี2553.pdf', '玛哈沙拉仁大学音乐学院管理与运行规章（佛历2553年，2010年颁布）\n\n依据泰国《高等教育机构内部管理条例》（佛历2550年）第4条及大学理事会决议制定，本规章全面规范了音乐学院内部治理结构、学院理事会及院长职权、学术管理流程与运行机制，确保学院管理的高效性与规范化。\n\n点击下方按钮即可在屏幕上全屏查阅规章全文，或扫描二维码保存PDF文档至手机。\n官方文件下载：https://music.msu.ac.th/wp-content/uploads/2024/12/ข้อบังคับปี2553.pdf', 'uploads/pr/about/MusicMSU-F3.png', NULL, 'https://music.msu.ac.th/wp-content/uploads/2024/12/ข้อบังคับปี2553.pdf', NULL, 'สำนักงานเลขานุการ อาคารวิทยาลัยดุริยางคศิลป์', '7', '1', '1', '2026-10-26 14:18:34');
